//! TreeList — migrated to the declarative component model.
//!
//! The DevTools snapshot tree. Like TreeView: hover is render-only (an effect
//! repaints rows from a `row_map`, driven by a `rev` Signal), while expand /
//! collapse is structural (a partial rebuild of the body via `UIBuilder.rootAt`
//! + `registry.markLayoutDirty`). Each row registers its own typed (node, kind)
//! handler in `buildNode` — mirrors TreeView's `onRowEvent`/`rowHandler`: the
//! click modifier's action-id string is still autogenerated for the C-ABI hit
//! test, but dispatch resolves the row through `row_map` by the event's real
//! node id, not by parsing an id-string prefix.
//!
//! `hovered_node`, `getNodeGeometry`, `getContentHeight` and `setSnapshot` keep
//! their old signatures: the inspector reads `hovered_node` to drive the target
//! overlay and sizes the surrounding ScrollView from the content height.
//! Hosted by ScrollView through the `component.Child` handle.

const std = @import("std");
const builder_mod = @import("builder.zig");
const component = @import("component.zig");
const signals = @import("../core/signals.zig");
const events = @import("events.zig");
const props = @import("../core/properties.zig");
const reg = @import("../core/registry.zig");
const theme_mod = @import("theme.zig");

pub const TreeNode = struct {
    id: usize,
    node_type: []const u8,
    expanded: bool = true,
    x: f64 = 0,
    y: f64 = 0,
    w: f64 = 0,
    h: f64 = 0,
    children: std.array_list.Managed(TreeNode),
};

const RowInfo = struct { node_id: usize, row: reg.NodeId };

pub const TreeList = struct {
    allocator: std.mem.Allocator,
    root: ?TreeNode = null,
    expanded_nodes: std.AutoHashMap(usize, void),
    hovered_node: i32,

    rev: signals.Signal(u32),
    scope: signals.Scope,
    store: ?*props.PropertyStore = null,
    theme: @import("theme.zig").Theme = .{},
    root_id: reg.NodeId = reg.NULL_NODE,
    row_map: std.array_list.Managed(RowInfo),
    bound: bool = false,
    router: ?*events.EventRouter = null,

    // O(1) hover repaint bookkeeping (see TreeView). `updateVisuals` repaints only
    // the outgoing/incoming hovered rows; a structural (re)build sets `full_repaint`
    // so freshly-built rows are painted once. `paint_visits` is a test hook.
    last_hovered: i32 = -1,
    full_repaint: bool = true,
    paint_visits: usize = 0,

    pub fn init(allocator: std.mem.Allocator) !*TreeList {
        const self = try allocator.create(TreeList);
        self.* = .{
            .allocator = allocator,
            .expanded_nodes = std.AutoHashMap(usize, void).init(allocator),
            .hovered_node = -1,
            .rev = signals.Signal(u32).init(allocator, 0),
            .scope = signals.Scope.init(allocator),
            .row_map = std.array_list.Managed(RowInfo).init(allocator),
        };
        return self;
    }

    fn bumpRev(self: *TreeList) void {
        self.rev.set(self.rev.peek() +% 1);
    }

    /// One typed handler for every row (click + hover edges): resolves the tree
    /// node by matching the event's node against `row_map`. Mirrors TreeView's
    /// `onRowEvent`.
    fn onRowEvent(self: *TreeList, ev: events.Event) void {
        const id = blk: {
            for (self.row_map.items) |info| {
                if (info.row == ev.node_id) break :blk info.node_id;
            }
            return;
        };
        if (std.mem.eql(u8, ev.name, "click")) {
            if (self.root) |*root| {
                var had_children = false;
                if (self.toggleNodeRecursive(root, id, &had_children) and had_children) {
                    self.rebuildBody(); // structural
                }
            }
        } else if (std.mem.eql(u8, ev.name, "mouse_enter")) {
            const idi: i32 = @intCast(id);
            if (self.hovered_node != idi) {
                self.hovered_node = idi;
                self.bumpRev();
            }
        } else if (std.mem.eql(u8, ev.name, "mouse_leave")) {
            const idi: i32 = @intCast(id);
            if (self.hovered_node == idi) {
                self.hovered_node = -1;
                self.bumpRev();
            }
        }
    }

    fn rowHandler(self: *TreeList) events.Handler {
        const Wrap = struct {
            fn call(erased: ?*anyopaque, ev: events.Event) void {
                @as(*TreeList, @ptrCast(@alignCast(erased.?))).onRowEvent(ev);
            }
        };
        return .{ .ptr = self, .call = Wrap.call };
    }

    fn toggleNodeRecursive(self: *TreeList, node: *TreeNode, target_id: usize, had_children: *bool) bool {
        if (node.id == target_id) {
            node.expanded = !node.expanded;
            if (node.expanded) {
                self.expanded_nodes.put(node.id, {}) catch {};
            } else {
                _ = self.expanded_nodes.remove(node.id);
            }
            had_children.* = node.children.items.len > 0;
            return true;
        }
        for (node.children.items) |*child| {
            if (self.toggleNodeRecursive(child, target_id, had_children)) return true;
        }
        return false;
    }

    // ── Snapshot loading ────────────────────────────────────────────────────────

    pub fn setSnapshot(self: *TreeList, json_str: []const u8) !void {
        if (self.root) |*root| {
            deinitNode(self.allocator, root);
            self.root = null;
        }
        var parsed = try std.json.parseFromSlice(std.json.Value, self.allocator, json_str, .{});
        defer parsed.deinit();
        self.root = try self.buildTree(self.allocator, parsed.value);
    }

    fn buildTree(self: *TreeList, allocator: std.mem.Allocator, val: std.json.Value) anyerror!TreeNode {
        var node = TreeNode{
            .id = 0,
            // Always owned (duped) so deinitNode can free it unconditionally —
            // the parsed JSON it may come from is freed right after buildTree.
            .node_type = try allocator.dupe(u8, "unknown"),
            .children = std.array_list.Managed(TreeNode).init(allocator),
        };
        if (val == .object) {
            const obj = val.object;
            if (obj.get("id")) |v| if (v == .integer) {
                node.id = @intCast(v.integer);
                node.expanded = self.expanded_nodes.contains(node.id);
            };
            if (obj.get("type")) |v| if (v == .string) {
                allocator.free(node.node_type);
                node.node_type = try allocator.dupe(u8, v.string);
            };
            if (obj.get("x")) |v| if (v == .float) {
                node.x = v.float;
            };
            if (obj.get("y")) |v| if (v == .float) {
                node.y = v.float;
            };
            if (obj.get("width")) |v| if (v == .float) {
                node.w = v.float;
            };
            if (obj.get("height")) |v| if (v == .float) {
                node.h = v.float;
            };
            if (obj.get("children")) |cv| if (cv == .array) {
                for (cv.array.items) |child_val| {
                    try node.children.append(try self.buildTree(allocator, child_val));
                }
            };
        }
        return node;
    }

    fn countVisibleNodes(self: *TreeList, node: *const TreeNode) usize {
        var count: usize = 1;
        if (node.expanded) {
            for (node.children.items) |*child| {
                count += self.countVisibleNodes(child);
            }
        }
        return count;
    }

    pub fn getContentHeight(self: *TreeList) f32 {
        var count: usize = 0;
        if (self.root) |*root| {
            count = self.countVisibleNodes(root);
        }
        return @as(f32, @floatFromInt(count)) * 30.0 + 200.0;
    }

    pub fn getNodeGeometry(self: *TreeList, id: usize) ?[4]f32 {
        if (self.root) |*root| {
            return self.findGeometry(root, id);
        }
        return null;
    }

    fn findGeometry(self: *TreeList, node: *const TreeNode, id: usize) ?[4]f32 {
        if (node.id == id) {
            return .{ @floatCast(node.x), @floatCast(node.y), @floatCast(node.w), @floatCast(node.h) };
        }
        for (node.children.items) |*child| {
            if (self.findGeometry(child, id)) |rect| return rect;
        }
        return null;
    }

    // ── build ─────────────────────────────────────────────────────────────────

    pub fn build(self: *TreeList, ctx: *component.BuildContext) !void {
        const b = ctx.builder;
        self.store = b.store;
        self.theme = b.theme;
        self.router = ctx.router;

        const root = try b.openNodeKeyed(.box, null);
        self.root_id = root;
        try b.width(root, 100, .percent);
        try b.height(root, 100, .percent);
        try b.background(root, b.theme.bg_input.r, b.theme.bg_input.g, b.theme.bg_input.b);

        try self.buildBody(b);

        b.close(); // root

        if (!self.bound) {
            _ = try self.scope.createEffect(self, updateVisuals);
            self.bound = true;
        }
        self.updateVisuals();
    }

    pub fn buildBody(self: *TreeList, b: *builder_mod.UIBuilder) !void {
        self.row_map.clearRetainingCapacity();
        if (self.root) |*tree_root| {
            try self.buildNode(b, tree_root, 0);
            const spacer = try b.openNodeKeyed(.box, null);
            try b.width(spacer, 100, .percent);
            try b.height(spacer, 200, .px);
            b.close();
        } else {
            _ = try b.addText("No Snapshot Available");
        }
        // Rows rebuilt from scratch: the next visuals pass paints all of them.
        self.full_repaint = true;
    }

    fn buildNode(self: *TreeList, b: *builder_mod.UIBuilder, node: *const TreeNode, depth: usize) !void {
        const indent_px: f32 = @floatFromInt(depth * 20);

        const row = try b.openNodeKeyed(.box, null);
        try b.width(row, 100, .percent);
        try b.height(row, 30, .px);
        try b.padding(row, 7, 0, 0, indent_px);
        try b.flexRow(row);
        if (self.theme.border_width > 0) {
            try b.borderWidth(row, self.theme.border_width);
            try b.borderColorOf(row, self.theme.border_color);
        }

        // Hit modifiers keep an autogenerated action-id (C-ABI channel unchanged);
        // dispatch goes through the typed (node, kind) handler registered below.
        var idbuf: [16]u8 = undefined;
        const auto_id = std.fmt.bufPrint(&idbuf, "n{d}", .{row}) catch "n";
        try b.clickable(row, auto_id);
        try b.hoverable(row, auto_id);
        if (self.router) |r| {
            const h = self.rowHandler();
            try r.onNode(row, .click, h);
            try r.onNode(row, .mouse_enter, h);
            try r.onNode(row, .mouse_leave, h);
        }

        const icon_str = if (node.children.items.len > 0)
            (if (node.expanded) "[-]" else "[+]")
        else
            "   ";
        const icon = try b.addText(icon_str);
        try b.width(icon, 30, .px);
        try b.height(icon, 20, .px);
        try b.pointerEventsNone(icon);

        var label_buf: [256]u8 = undefined;
        const label = try std.fmt.bufPrint(&label_buf, "{s} {d}   [x:{d:.1} y:{d:.1} w:{d:.1} h:{d:.1}]", .{ node.node_type, node.id, node.x, node.y, node.w, node.h });
        const lbl_node = try b.addText(label);
        try b.height(lbl_node, 20, .px);
        try b.pointerEventsNone(lbl_node);

        b.close(); // row

        try self.row_map.append(.{ .node_id = node.id, .row = row });

        if (node.expanded) {
            for (node.children.items) |*child| {
                try self.buildNode(b, child, depth + 1);
            }
        }
    }

    fn rebuildBody(self: *TreeList) void {
        component.rebuildTreeBody(self);
    }

    fn rowFor(self: *TreeList, id: usize) ?RowInfo {
        for (self.row_map.items) |info| {
            if (info.node_id == id) return info;
        }
        return null;
    }

    fn paintRow(self: *TreeList, info: RowInfo, hovered: bool) void {
        const store = self.store orelse return;
        const c = if (hovered) theme_mod.Theme.stateLayer(self.theme.bg_surface, self.theme.text, .hover) else self.theme.bg_surface;
        store.setStyle(info.row, .background, props.PropValue.rgbA(c.r, c.g, c.b, @as(f32, @floatFromInt(c.a)) / 255.0)) catch {};
        self.paint_visits += 1;
    }

    pub fn updateVisuals(self: *TreeList) void {
        if (self.store == null) return;
        _ = self.rev.get(); // subscribe to hover changes
        self.paint_visits = 0;

        if (self.full_repaint) {
            for (self.row_map.items) |info| {
                self.paintRow(info, self.hovered_node == @as(i32, @intCast(info.node_id)));
            }
            self.full_repaint = false;
        } else if (self.last_hovered != self.hovered_node) {
            // Only the row losing hover and the row gaining it change.
            if (self.last_hovered >= 0) {
                if (self.rowFor(@intCast(self.last_hovered))) |info| self.paintRow(info, false);
            }
            if (self.hovered_node >= 0) {
                if (self.rowFor(@intCast(self.hovered_node))) |info| self.paintRow(info, true);
            }
        }
        self.last_hovered = self.hovered_node;
    }

    fn deinitNode(allocator: std.mem.Allocator, node: *TreeNode) void {
        for (node.children.items) |*child| deinitNode(allocator, child);
        node.children.deinit();
        allocator.free(node.node_type);
    }

    pub fn deinit(self: *TreeList) void {
        self.scope.deinit();
        self.rev.deinit();
        self.row_map.deinit();
        if (self.root) |*root| {
            deinitNode(self.allocator, root);
            self.root = null;
        }
        self.expanded_nodes.deinit();
        self.allocator.destroy(self);
    }
};

// ── Tests ─────────────────────────────────────────────────────────────────────

const testing = std.testing;

test "TreeList snapshot, expand/collapse structural, hover render-only" {
    var registry = reg.UIRegistry.init(testing.allocator);
    defer registry.deinit();
    var store = props.PropertyStore.init(testing.allocator);
    defer store.deinit();
    store.setRegistry(&registry);
    var bld = component.UIBuilder.init(&registry, &store);
    bld.theme = .{ .bg_input = .{ .r = 25, .g = 25, .b = 30 }, .bg_surface = .{ .r = 40, .g = 40, .b = 45, .a = 255 }, .text = .{ .r = 236, .g = 237, .b = 240 } };

    var router = events.EventRouter.init(testing.allocator);
    defer router.deinit();
    var ctx = component.BuildContext.initWithRouter(&bld, &router);

    var tl = try TreeList.init(testing.allocator);
    defer tl.deinit();

    // A root (id 1, expanded) with two children (ids 2, 3).
    try tl.setSnapshot(
        \\{"id":1,"type":"box","x":0.0,"y":0.0,"width":100.0,"height":40.0,
        \\ "children":[{"id":2,"type":"text"},{"id":3,"type":"text"}]}
    );

    try tl.build(&ctx);
    // Snapshot nodes start collapsed (none in expanded_nodes) → only the root row.
    try testing.expectEqual(@as(usize, 1), tl.row_map.items.len);

    const rootRow = struct {
        fn find(t: *TreeList) reg.NodeId {
            for (t.row_map.items) |r| if (r.node_id == 1) return r.row;
            unreachable;
        }
    }.find;

    // Expand root (id 1) → children rows appear (structural).
    _ = router.route(.{ .name = "click", .id = "", .node_id = rootRow(tl) });
    try testing.expectEqual(@as(usize, 3), tl.row_map.items.len);
    try testing.expect(tl.expanded_nodes.contains(1));

    // Collapse again → back to the root row.
    _ = router.route(.{ .name = "click", .id = "", .node_id = rootRow(tl) });
    try testing.expectEqual(@as(usize, 1), tl.row_map.items.len);
    try testing.expect(!tl.expanded_nodes.contains(1));

    // Hover the root row → its row gets the hover tint; geometry lookup works.
    _ = router.route(.{ .name = "mouse_enter", .id = "", .node_id = rootRow(tl) });
    try testing.expectEqual(@as(i32, 1), tl.hovered_node);
    const r1 = tl.getNodeGeometry(1).?;
    try testing.expectApproxEqAbs(@as(f32, 100.0), r1[2], 0.001);
    const root_row = blk: {
        for (tl.row_map.items) |r| if (r.node_id == 1) break :blk r;
        unreachable;
    };
    const expected_hover_c = theme_mod.Theme.stateLayer(tl.theme.bg_surface, tl.theme.text, .hover);
    try testing.expectApproxEqAbs(@as(f32, @floatFromInt(expected_hover_c.r)) / 255.0, store.getStyle(root_row.row, .background).?.color.r, 0.001);

    // Leave → tint reverts to the surface color.
    _ = router.route(.{ .name = "mouse_leave", .id = "", .node_id = root_row.row });
    try testing.expectEqual(@as(i32, -1), tl.hovered_node);
    try testing.expectApproxEqAbs(@as(f32, 40.0 / 255.0), store.getStyle(root_row.row, .background).?.color.r, 0.001);
}
